    from scipy import stats

    # Load data
    df = pd.read_csv('/data/GODREJIND.csv')

    # Extract column
    column_data = df['Total Traded Quantity'].dropna()

    # Perform Shapiro-Wilk test
    stat, p_value = stats.shapiro(column_data)

    # Output results
    print(f"Shapiro-Wilk Test Statistic: {stat}")
    print(f"p-value: {p_value}")

    # Interpret results
    alpha = 0.05
    if p_value < alpha:
